#include <stdio.h>
#include <string.h>

int main() {
    char greeting[20] = "Hello";
    strcat(greeting, ", World!");
    printf("%s (length %zu)\n", greeting, strlen(greeting));

    char a[] = "cat", b[] = "cat";
    if (strcmp(a, b) == 0) {         // 0 means equal — NOT a boolean 'true'
        printf("Equal\n");
    }

    char *pos = strstr(greeting, "World");
    printf("%s\n", pos);              // "World!" — from the match onward
    return 0;
}
